data.transform:
const assetId = $.assetId || "";
const tz = $.tz || $momentTzGuess();

if (!assetId) {
  return { error: "No assetId provided", assetId: null };
}

const now = $moment().tz(tz);
const nowUtc = now.format('YYYY-MM-DDTHH:mm:ss.SSSZ');

const sparklineStart = $moment(now).subtract(1, 'hour').format('YYYY-MM-DDTHH:mm:ss.SSSZ');
const hourlyStart = $moment(now).subtract(7, 'days').startOf('hour').format('YYYY-MM-DDTHH:mm:ss.SSSZ');

return {
  assetId,
  timezone: tz,
  boundaries: {
    now: nowUtc,
    sparklineStart,
    hourlyStart
  }
};

data.query:
query AssetTelemetryLive(
  $assetId: String!
  $sparklineStart: DateTime!
) {
  # Asset info
  asset: asset(
    where: { id: { _eq: $assetId } }
    first: 1
  ) {
    edges {
      node {
        id
        code
        name
        status
        criticality
        manufacturer
        model
        serialNumber
        workcenterId
        workcenter {
          id
          code
          name
        }
      }
    }
  }

  # DataPoint config
  dataPoints: dataPoint(
    where: {
      _and: [
        { assetId: { _eq: $assetId } }
        { enabled: { _eq: true } }
        { historize: { _eq: true } }
        { _or: [
          { dataType: { _eq: "Float" } }
          { dataType: { _eq: "Int" } }
        ]}
      ]
    }
    orderBy: [{ field: category, direction: asc }, { field: code, direction: asc }]
  ) {
    edges {
      node {
        id
        code
        displayName
        name
        category
        dataType
        isCritical
        frequency
        setPoint
        tolerance
        lowerLimit
        lowerWarning
        upperWarning
        upperLimit
        unit {
          id
          code
          name
        }
      }
    }
  }

  # Latest raw values
  latestRaw: telemetryRaw(
    where: {
      dataPoint: {
        _and: [
          { assetId: { _eq: $assetId } }
          { enabled: { _eq: true } }
          { historize: { _eq: true } }
          { _or: [
            { dataType: { _eq: "Float" } }
            { dataType: { _eq: "Int" } }
          ]}
        ]
      }
    }
    orderBy: [{ field: recordedAt, direction: desc }]
    first: 500
  ) {
    edges {
      node {
        value
        quality
        qualityCode
        recordedAt
        dataPointId
      }
    }
  }

  # Sparkline data (last 1 hour)
  sparklineRaw: telemetryRaw(
    where: {
      _and: [
        { recordedAt: { _gte: $sparklineStart } }
        { dataPoint: {
          _and: [
            { assetId: { _eq: $assetId } }
            { enabled: { _eq: true } }
            { historize: { _eq: true } }
            { _or: [
              { dataType: { _eq: "Float" } }
              { dataType: { _eq: "Int" } }
            ]}
          ]
        }}
      ]
    }
    orderBy: [{ field: recordedAt, direction: asc }]
    first: 5000
  ) {
    edges {
      node {
        value
        quality
        recordedAt
        dataPointId
      }
    }
  }
}

data.transform:
const timezone = $.timezone || $momentTzGuess();
const nowMs = $moment().valueOf();

const n = (v) => v || 0;

const extractNodes = (data) => {
  if (!data) return [];
  if (Array.isArray(data)) return data.map(e => e.node);
  if (data.edges) return data.edges.map(e => e.node);
  return [];
};

const asset = extractNodes($.asset)?.[0] || null;
const dpNodes = extractNodes($.dataPoints);
const latestRawNodes = extractNodes($.latestRaw);
const sparklineNodes = extractNodes($.sparklineRaw);

// Build datapoint config map
const dpMap = {};
const categories = {};

dpNodes.forEach(dp => {
  dpMap[dp.id] = {
    id: dp.id,
    code: dp.code,
    displayName: dp.displayName || dp.name || dp.code,
    category: dp.category || "General",
    dataType: dp.dataType,
    isCritical: dp.isCritical,
    frequency: dp.frequency,
    setPoint: dp.setPoint,
    tolerance: dp.tolerance,
    lowerLimit: dp.lowerLimit,
    lowerWarning: dp.lowerWarning,
    upperWarning: dp.upperWarning,
    upperLimit: dp.upperLimit,
    unitCode: dp.unit?.code || dp.unit?.name || "",
    unitName: dp.unit?.name || ""
  };
  categories[dp.category || "General"] = true;
});

// Deduplicate latest raw → one per dataPointId
const latestByDp = {};
latestRawNodes.forEach(raw => {
  if (!latestByDp[raw.dataPointId]) {
    latestByDp[raw.dataPointId] = raw;
  }
});

// Group sparkline by datapoint
const sparklineByDp = {};
sparklineNodes.forEach(raw => {
  if (!sparklineByDp[raw.dataPointId]) {
    sparklineByDp[raw.dataPointId] = [];
  }
  sparklineByDp[raw.dataPointId].push({
    value: raw.value,
    time: raw.recordedAt
  });
});

// Status classification
const classifyStatus = (value, dp) => {
  if (value == null) return "unknown";
  if (dp.upperLimit != null && value > dp.upperLimit) return "alarm";
  if (dp.lowerLimit != null && value < dp.lowerLimit) return "alarm";
  if (dp.upperWarning != null && value > dp.upperWarning) return "warning";
  if (dp.lowerWarning != null && value < dp.lowerWarning) return "warning";
  return "good";
};

const getStatusColor = (status) => {
  switch (status) {
    case "alarm": return "#ef4444";
    case "warning": return "#f59e0b";
    case "good": return "#10b981";
    case "stale": return "#6b7280";
    case "badQuality": return "#7c3aed";
    default: return "#6b7280";
  }
};

const getTrend = (sparkline) => {
  if (!sparkline || sparkline.length < 3) return "stable";
  const recent = sparkline.slice(-3).map(s => s.value);
  const diff = recent[recent.length - 1] - recent[0];
  const vals = sparkline.map(s => s.value);
  let minVal = vals[0];
  let maxVal = vals[0];
  for (let i = 1; i < vals.length; i++) {
    if (vals[i] < minVal) minVal = vals[i];
    if (vals[i] > maxVal) maxVal = vals[i];
  }
  const range = maxVal - minVal;
  if (range === 0) return "stable";
  const pctChange = Math.abs(diff) / range;
  if (pctChange < 0.1) return "stable";
  return diff > 0 ? "rising" : "falling";
};

// Build current values
const currentValues = [];
let alarmCount = 0;
let warningCount = 0;
let goodCount = 0;
let badQualityCount = 0;
let staleCount = 0;

Object.keys(dpMap).forEach(dpId => {
  const dp = dpMap[dpId];
  const latest = latestByDp[dpId];
  const sparkline = sparklineByDp[dpId] || [];

  const value = latest ? latest.value : null;
  const quality = latest ? latest.quality : "Unknown";
  const recordedAt = latest ? latest.recordedAt : null;
  const staleSeconds = recordedAt ? Math.floor((nowMs - $moment(recordedAt).valueOf()) / 1000) : null;
  const isStale = staleSeconds != null && dp.frequency > 0 && staleSeconds > (dp.frequency / 1000) * 3;
  const isBadQuality = quality !== "Good" && quality !== "Unknown";

  let status;
  if (isBadQuality) {
    status = "badQuality";
    badQualityCount++;
  } else if (isStale) {
    status = "stale";
    staleCount++;
  } else {
    status = classifyStatus(value, dp);
    if (status === "alarm") alarmCount++;
    else if (status === "warning") warningCount++;
    else goodCount++;
  }

  currentValues.push({
    dataPointId: dpId,
    code: dp.code,
    displayName: dp.displayName,
    category: dp.category,
    isCritical: dp.isCritical,
    value,
    quality,
    unitCode: dp.unitCode,
    unitName: dp.unitName,
    recordedAt,
    staleSeconds,
    isStale,
    setPoint: dp.setPoint,
    tolerance: dp.tolerance,
    lowerLimit: dp.lowerLimit,
    lowerWarning: dp.lowerWarning,
    upperWarning: dp.upperWarning,
    upperLimit: dp.upperLimit,
    status,
    statusColor: getStatusColor(status),
    sparkline: sparkline.map(s => s.value),
    trend: getTrend(sparkline)
  });
});

currentValues.sort((a, b) => {
  if (a.isCritical !== b.isCritical) return b.isCritical ? 1 : -1;
  if (a.category !== b.category) return a.category.localeCompare(b.category);
  return a.code.localeCompare(b.code);
});

const criticalPoints = currentValues.filter(cv => cv.isCritical);

return {
  assetId: $.assetId,
  asset: asset ? {
    id: asset.id,
    code: asset.code,
    name: asset.name,
    status: asset.status,
    criticality: asset.criticality,
    manufacturer: asset.manufacturer,
    model: asset.model,
    serialNumber: asset.serialNumber,
    workcenterId: asset.workcenterId,
    workcenter: asset.workcenter
  } : null,
  timezone,
  lastRefresh: $moment().format('YYYY-MM-DDTHH:mm:ss.SSSZ'),
  lastRefreshFormatted: $moment().tz(timezone).format('MMM D, YYYY h:mm:ss A'),

  alarmState: {
    hasAlarms: alarmCount > 0 || warningCount > 0,
    alarmCount,
    warningCount,
    goodCount,
    badQualityCount,
    staleCount,
    totalPoints: currentValues.length
  },

  currentValues,
  criticalPoints,
  categories: Object.keys(categories).sort(),
  dpMap,

  config: {
    hourlyWindowDays: 7,
    sparklineWindowMinutes: 60,
    dataPointCount: dpNodes.length
  }
};

